import ctypes
import os
import sys

# Loads the DLL generated by DelSafe (delsafe_math.dll)
dll_path = os.path.join(os.path.dirname(__file__), "bin", "delsafe_math.dll")
if not os.path.exists(dll_path):
    print(f"Error: DLL not found at {dll_path}")
    sys.exit(1)

lib = ctypes.CDLL(dll_path)

# Defines the matching Point2D struct
class Point2D(ctypes.Structure):
    _fields_ = [
        ("x", ctypes.c_double),
        ("y", ctypes.c_double)
    ]

# Configures signatures of functions exported from DelSafe
lib.AddIntegers.argtypes = [ctypes.c_int32, ctypes.c_int32]
lib.AddIntegers.restype = ctypes.c_int32

lib.MultiplyIntegers.argtypes = [ctypes.c_int32, ctypes.c_int32]
lib.MultiplyIntegers.restype = ctypes.c_int32

lib.CreatePoint.argtypes = [ctypes.c_double, ctypes.c_double]
lib.CreatePoint.restype = Point2D

lib.AddPoints.argtypes = [Point2D, Point2D]
lib.AddPoints.restype = Point2D

lib.NormSquared.argtypes = [Point2D]
lib.NormSquared.restype = ctypes.c_double

# 1. Integer tests
res_sum = lib.AddIntegers(15, 27)
print(f"[Python ctypes] AddIntegers(15, 27) = {res_sum}")
assert res_sum == 42, f"Expected 42, got {res_sum}"

res_mult = lib.MultiplyIntegers(6, 7)
print(f"[Python ctypes] MultiplyIntegers(6, 7) = {res_mult}")
assert res_mult == 42, f"Expected 42, got {res_mult}"

# 2. Point2D struct tests
p1 = lib.CreatePoint(3.0, 4.0)
print(f"[Python ctypes] CreatePoint(3.0, 4.0) -> ({p1.x}, {p1.y})")
assert p1.x == 3.0 and p1.y == 4.0

p2 = lib.CreatePoint(1.0, 2.0)
p3 = lib.AddPoints(p1, p2)
print(f"[Python ctypes] AddPoints(p1, p2) -> ({p3.x}, {p3.y})")
assert p3.x == 4.0 and p3.y == 6.0

norm = lib.NormSquared(p1)
print(f"[Python ctypes] NormSquared(p1) -> {norm}")
assert norm == 25.0, f"Expected 25.0, got {norm}"

print("\n>>> SUCCESS! All Python -> DelSafe DLL FFI tests passed with 100% accuracy! <<<")
